"""Trama: identidade, navegação retrátil e consulta com contexto."""
from pathlib import Path
import html, re
from highlight import highlight
E=lambda x:html.escape(str(x),quote=True)
def inline(x):
    return re.sub(r'`([^`]+)`',lambda m:'<code>'+m.group(1)+'</code>',E(x))
ICONS={
'home':'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',
'grid':'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
'panel':'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16m8-12-3 4 3 4"/>',
'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>',
'moon':'<path d="M20 14a8.5 8.5 0 0 1-10-10 8.5 8.5 0 1 0 10 10Z"/>',
'arrow':'<path d="M5 12h14m-5-5 5 5-5 5"/>',
'code':'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',
'data':'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',
'close':'<path d="m6 6 12 12M6 18 18 6"/>',
'check':'<path d="m4 12 5 5L20 6"/>'}
def svg(key,cls=''):
    return f'<svg class="ui-icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[key]}</svg>'
TRACK_ICONS={'data':'data','code':'code','DB':'data','SQL':'code','FAB':'data','BI':'data','PQ':'data','XL':'data','API':'data','PA':'data','APP':'data','AI':'data','HTML':'code','CSS':'code','JS':'code'}
def track_icon(track):
    configured=track.get('icon','')
    return svg(TRACK_ICONS[configured]) if configured in TRACK_ICONS else E(configured)
def section_editors(section,track):
    if section.get('codeBlocks'):
        return ''.join(editor(b['code'],b['language'],b['label'],b['label']) for b in section['codeBlocks'])
    return editor(section['code'],track['id'],track['name']+' · EXEMPLO DIDÁTICO') if section.get('code') else ''
def editor(code,lang,label='EXEMPLO',name='código'):
    return f'<div class="code-wrap ref-code"><div class="code-meta"><span><i class="editor-dot"></i>{E(label)}</span><button class="copy-button" data-copy aria-label="Copiar {E(name)}">Copiar</button></div><pre><code>{highlight(code,lang)}</code></pre></div>'
def lesson_count(n,initial=False):
    return f"{n} {'aula' if n==1 else 'aulas'}"+(' inicial' if n==1 else ' iniciais') if initial else f"{n} {'aula' if n==1 else 'aulas'}"
def social_icon(key):
    # LinkedIn e envelope usam o mesmo desenho presente no portfólio do titular.
    paths={
        'linkedin':'M5.3 7.8H1.1V21h4.2V7.8ZM3.2 1.2A2.4 2.4 0 1 0 3.2 6a2.4 2.4 0 0 0 0-4.8ZM21 13.4c0-4-2.1-5.9-5-5.9-2.3 0-3.4 1.3-4 2.2V7.8H7.8V21H12v-6.5c0-1.7.33-3.4 2.5-3.4 2.2 0 2.2 2 2.2 3.5V21H21v-7.6Z',
        'contact':'M3 4h18a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm9 8 8-5V6l-8 5-8-5v1l8 5Z'}
    if key=='portfolio':
        return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="6" width="18" height="15" rx="3"/><path d="M8 6V3h8v3M3 12h18m-9-2v4"/></svg>'
    return f'<svg class="ui-icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="{paths[key]}"/></svg>'

def render_site(cfg,tracks,lessons,refs,out):
    bytrack={t['id']:[l for l in lessons if l['track']==t['id']] for t in tracks}
    def base(title,body,prefix='',active='home',pageclass='',route='index.html'):
        nav=[('home','home','Visão geral',prefix+'index.html'),('catalog','grid','Trilhas',prefix+'index.html#catalogo'),('reference','search','Consultas rápidas',prefix+'consultas.html')]
        links=''.join(f'<a class="nav-link {"current" if active==key else ""}" href="{url}" title="{name}" '+('aria-current="page"' if active==key else '')+f'>{svg(ico)}<span>{name}</span></a>' for key,ico,name,url in nav)
        creator=cfg.get('creator',{})
        def social_links(placement):
            items=[('portfolio','portfolio_url','Portfólio'),('linkedin','linkedin_url','LinkedIn'),('contact','contact_url','Contato e sugestões')]
            return ''.join(f'<a class="creator-link" data-creator-link="{key}" data-placement="{placement}" href="{E(creator[prop])}" target="_blank" rel="noopener noreferrer" title="{label} — abre em nova aba" aria-label="{label} — abre em nova aba">{social_icon(key)}<span>{label}</span></a>' for key,prop,label in items if creator.get(prop))
        socials=social_links('sidebar')
        creator_nav=f'<nav class="creator-shortcuts" aria-label="Links profissionais de {E(creator.get("name","criador"))}">{socials}</nav>' if socials else ''
        a=cfg.get('analytics',{})
        enabled=a.get('enabled',False)
        analytics_attrs=(f'data-analytics-id="{E(a["measurement_id"])}" data-analytics-base="{E(a["site_url"])}" data-preference-days="{a.get("preference_days",180)}" data-collection-mode="{E(a["collection_mode"])}"' if enabled else '')
        notice=(f'<dialog class="analytics-notice" id="analytics-notice" aria-labelledby="metrics-notice-title" aria-describedby="metrics-notice-description"><button class="icon-button notice-close" data-notice-dismiss aria-label="Fechar aviso de métricas">{svg("close")}</button><span class="eyebrow">TRANSPARÊNCIA</span><h2 id="metrics-notice-title">Como medimos o uso da Trama</h2><p id="metrics-notice-description">Usamos o Google Analytics para medir acessos às páginas e navegação e melhorar o portal. A ferramenta usa cookies para distinguir navegadores e sessões.</p><p>Não enviamos o texto das buscas nem o código copiado. A medição pode começar antes de você fechar este aviso; você pode desativá-la no rodapé.</p><p class="notice-preference" id="notice-preference" hidden></p><div class="notice-actions"><a class="button secondary" href="{prefix}privacidade.html">Privacidade</a><button class="button primary" data-notice-dismiss autofocus>Entendi</button></div></dialog>' if enabled else '')
        metrics_controls=('<button data-notice-open>Sobre as métricas</button><button data-metrics-toggle aria-pressed="false">Desativar métricas</button><span id="metrics-status" role="status" aria-live="polite"></span>' if enabled else '')
        privacy_controls=f'<div class="privacy-controls"><a href="{prefix}termos.html">Termos de Uso</a><a href="{prefix}privacidade.html">Privacidade</a>{metrics_controls}</div>'
        analytics_script=f'<script src="{prefix}assets/analytics.js" defer></script>' if enabled else ''
        return f'''<!doctype html><html lang="pt-BR" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Trama: aprenda ferramentas, entenda os exemplos e consulte com contexto."><meta name="theme-color" content="#20505A"><meta name="referrer" content="strict-origin-when-cross-origin"><title>{E(title)} · Trama</title><link rel="icon" href="{prefix}assets/brand/trama-isotipo.svg"><link rel="stylesheet" href="{prefix}assets/site.css"></head><body class="{pageclass}" {analytics_attrs} data-page-path="{E(route)}"><a class="skip" href="#conteudo">Pular para o conteúdo</a><aside class="sidebar" id="sidebar"><a class="brand" href="{prefix}index.html" aria-label="Trama, início"><img class="logo-light" src="{prefix}assets/brand/trama-logo.svg" alt="Trama — rede de conhecimento"><img class="logo-dark" src="{prefix}assets/brand/trama-logo-inverse.svg" alt="Trama — rede de conhecimento"><img class="logo-symbol" src="{prefix}assets/brand/trama-isotipo.svg" alt="Trama"></a><div class="sidebar-divider"></div><p class="nav-label">EXPLORAR</p><nav aria-label="Navegação principal">{links}</nav>{creator_nav}<button class="collapse-button" id="sidebar-toggle" aria-label="Recolher menu lateral" aria-expanded="true" aria-controls="sidebar">{svg('panel')}<span>Recolher menu</span></button><button class="mobile-close icon-button" id="menu-close" aria-label="Fechar navegação">{svg('close')}</button></aside><button class="nav-backdrop" id="nav-backdrop" aria-label="Fechar navegação" hidden></button><div class="shell"><header class="topbar"><button class="mobile-menu icon-button" id="menu-open" aria-label="Abrir navegação" aria-expanded="false" aria-controls="sidebar">{svg('menu')}</button><div class="breadcrumbs"><span>Trama</span><span class="crumb-slash">/</span><strong>{E(title)}</strong></div><div class="top-actions"><a class="search-shortcut" href="{prefix}consultas.html" aria-label="Buscar referência">{svg('search')}<span>Buscar referência</span><kbd>/</kbd></a><button class="icon-button theme-toggle" id="theme-toggle" aria-label="Ativar tema escuro" aria-pressed="false">{svg('moon','moon-icon')}{svg('sun','sun-icon')}</button></div></header><main id="conteudo" tabindex="-1">{body}</main><footer class="site-footer"><div class="footer-intro"><strong>trama<span> · conhecimento em conexão</span></strong><span class="creator-name">Por {E(creator.get("name","Kaíque Passaros"))}</span></div><div class="footer-links"><nav class="footer-socials" aria-label="Links profissionais">{social_links("footer")}</nav>{privacy_controls}<a href="{prefix}consultas.html">Consultar uma referência →</a></div></footer></div>{notice}<script src="{prefix}assets/site.js" defer></script>{analytics_script}</body></html>'''
    cards=[]
    for t in tracks:
        ls=bytrack[t['id']]; search=' '.join([t['name'],t['category'],t['description']]+t['topics']+[l['title'] for l in ls]); links=''.join(f'<li><a href="trilhas/{t["id"]}/{l["id"]}.html">{E(l["title"])}</a><span>{l["minutes"]} min</span></li>' for l in ls)
        cards.append(f'''<article class="track-card glass {E(t['color'])}" data-tilt data-track-card data-search="{E(search)}" data-category="{E(t['category'])}"><div class="track-card-top"><span class="tool-glyph">{track_icon(t)}</span><span class="tag">{E(t['category'])}</span></div><h3><a href="trilhas/{t['id']}/index.html">{E(t['name'])}</a></h3><p>{E(t['description'])}</p><div class="track-meta"><span>{lesson_count(len(ls))}</span><span class="meta-dot">·</span><span>Fundamentos</span></div><a class="track-link" href="trilhas/{t['id']}/index.html">Explorar trilha {svg('arrow')}</a><details class="course-outline"><summary>Ver sequência de aulas</summary><ol>{links}</ol><p>Conteúdo inicial. A trilha continua em expansão.</p></details></article>''')
    featured='''SELECT customer_id,
       SUM(total_amount) AS revenue
FROM orders
WHERE status = 'paid'
GROUP BY customer_id;'''
    home=f'''<section class="hero"><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span> ESTUDO + CONSULTA, EM CONEXÃO</span><h1>Aprender uma ferramenta.<br><em>Consultar quando precisar.</em></h1><p>Da primeira ideia à aplicação. Trilhas para construir sua base e referências para entender o código — não apenas copiar.</p><div class="hero-actions"><a class="button primary" href="trilhas/sql/index.html">Começar por SQL {svg('arrow')}</a><a class="button secondary" href="consultas.html">Explorar consultas {svg('search')}</a></div><div class="hero-topics"><span>Dados</span><span>BI & Analytics</span><span>Automação</span><span>Web</span></div></div><div class="hero-panel glass" data-tilt><div class="panel-head"><span class="tag">SQL / NA PRÁTICA</span><span class="panel-label">Aprenda com contexto</span></div><h2>De linhas a<br><em>decisões melhores.</em></h2><p>Quanto cada cliente gerou em pedidos pagos?</p>{editor(featured,'sql','SQL · EXEMPLO DIDÁTICO','exemplo SQL')}<div class="panel-outcome">{svg('check')}<span>Uma linha por cliente. Receita agregada.</span></div><a class="text-link" href="consultas.html">Entender a consulta {svg('arrow')}</a></div></section><div class="metric-strip"><div><strong>{len(tracks):02}</strong><span>trilhas de tecnologia</span></div><div><strong>{len(lessons):02}</strong><span>aulas iniciais</span></div><div><strong>{len(refs):02}</strong><span>referências com fontes</span></div></div><section class="section-block" id="catalogo"><div class="section-head"><div><span class="eyebrow">01 / EXPLORE AS TRILHAS</span><h2>Qual é o próximo fio?</h2><p>Escolha uma ferramenta. Construa sua base no seu ritmo.</p></div><a class="quiet-link" href="consultas.html">Já sabe o que procura? {svg('arrow')}</a></div><div class="catalog-controls"><label class="search-field">{svg('search')}<input id="track-search" type="search" placeholder="Buscar ferramenta, tema ou aula" aria-label="Buscar trilhas"></label><div class="filters" role="group" aria-label="Categorias"><button data-category-filter="all" aria-pressed="true">Todas <span>{len(tracks)}</span></button>{''.join(f'<button data-category-filter="{E(c)}" aria-pressed="false">{E(c)}</button>' for c in sorted({t['category'] for t in tracks}))}</div></div><p id="track-count" class="result-count" role="status">{len(tracks)} trilhas disponíveis</p><div class="track-grid">{''.join(cards)}</div><div id="track-empty" class="empty-state" hidden><h3>Nenhuma trilha encontrada</h3><p>Tente outro termo ou limpe o filtro.</p><button id="clear-track-search" class="button secondary">Limpar busca</button></div></section><section class="reference-callout glass"><div><span class="eyebrow">02 / CENTRAL DE CONSULTA</span><h2>A sintaxe é só o começo.</h2><p>Entenda a intenção, acompanhe o exemplo e confira os limites. Cada referência aponta para a documentação oficial.</p></div><a class="button primary" href="consultas.html">Consultar agora {svg('arrow')}</a></section>'''
    (out/'index.html').write_text(base('Visão geral',home),encoding='utf-8')
    for t in tracks:
        td=out/'trilhas'/t['id'];td.mkdir(parents=True,exist_ok=True);ls=bytrack[t['id']]
        listitems=''.join(f'<a class="lesson-card glass" href="{l["id"]}.html"><span class="lesson-number">{i:02}</span><span class="lesson-card-copy"><span class="lesson-level">{E(l["level"])} · {l["minutes"]} MIN</span><strong>{E(l["title"])}</strong><span>{E(l["objective"])}</span></span>{svg("arrow")}</a>' for i,l in enumerate(ls,1))
        trackbody=f'''<section class="track-hero"><a class="back-link" href="../../index.html#catalogo">← Todas as trilhas</a><div class="track-hero-head"><span class="tool-glyph">{track_icon(t)}</span><span class="tag">{E(t['category'])}</span></div><span class="eyebrow">TRILHA INDEPENDENTE</span><h1>{E(t['name'])}</h1><p class="lead">{E(t['description'])}</p><div class="track-stats">{lesson_count(len(ls),True)} · exemplos e prática</div><div class="hero-actions"><a class="button primary" href="{ls[0]['id']}.html">Começar pela aula 1 {svg('arrow')}</a><a class="button secondary" href="../../consultas.html">Consultar referências</a></div></section><section class="track-body"><div class="section-head"><div><span class="eyebrow">SEQUÊNCIA DE APRENDIZAGEM</span><h2>Seu ponto de partida</h2><p>Módulos iniciais da trilha. Novas aulas entram após revisão.</p></div></div><div class="lesson-list">{listitems}</div><div class="topics-note glass"><strong>Mapa da trilha</strong><ul>{''.join(f'<li>{E(x)}</li>' for x in t['topics'])}</ul></div></section>'''
        (td/'index.html').write_text(base(t['name'],trackbody,'../../','catalog','course-page',route=f'trilhas/{t["id"]}/index.html'),encoding='utf-8')
        for i,l in enumerate(ls,1):
            toc=''.join(f'<a href="#sec-{n}">{E(sec["heading"])}</a>' for n,sec in enumerate(l['sections'],1))
            sections=''.join(f'<section class="lesson-section" id="sec-{n}"><span class="eyebrow">{n:02} / ENTENDA</span><h2>{E(sec["heading"])}</h2>'+''.join(f'<p>{inline(p)}</p>' for p in sec['paragraphs'])+section_editors(sec,t)+'</section>' for n,sec in enumerate(l['sections'],1))
            review=''.join(f'<details class="review-item"><summary>{E(x["question"])}</summary><p>{E(x["answer"])}</p></details>' for x in l['review'])
            sources=''.join(f'<li><a href="{E(r["url"])}" target="_blank" rel="noopener noreferrer">{E(r["label"])} ↗</a></li>' for r in l['references'])
            practice=f'<section class="lesson-section" id="pratica"><span class="eyebrow">PRATIQUE</span><h2>Transforme leitura em entendimento</h2><p>{inline(l["exercise"])}</p></section>' if l.get('exercise') else ''
            practice_link='<a href="#pratica">Prática</a>' if practice else ''
            lesson_toc=f'<aside class="lesson-toc glass"><span class="eyebrow">NESTA AULA</span>{toc}{practice_link}<a href="#erros">Revisão</a><a href="#fontes">Fontes oficiais</a></aside>'
            body=f'''<div class="lesson-shell">{lesson_toc}<article class="lesson-main"><a class="back-link" href="index.html">← Trilha de {E(t['name'])}</a><header class="lesson-head"><span class="eyebrow">AULA {i:02} · {E(l['level'])}</span><h1>{E(l['title'])}</h1><p class="lead">{inline(l['intro'])}</p><p class="lesson-meta">{l['minutes']} min de leitura · {E(l['prerequisites'])}</p><div class="objective-card glass"><strong>Ao final, você deve conseguir</strong><p>{E(l['objective'])}</p></div></header><div class="lesson-content">{sections}{practice}<section class="lesson-section" id="erros"><span class="eyebrow">REVISÃO</span><h2>Armadilhas frequentes</h2><ul class="pitfall-list">{''.join(f'<li>{E(x)}</li>' for x in l['pitfalls'])}</ul><h3>Confira o que ficou</h3>{review}</section><section class="lesson-section" id="fontes"><span class="eyebrow">FONTES</span><h2>Continue pela documentação</h2><ul class="source-list">{sources}</ul><p class="source-note">Confira versão, ambiente, permissões e dialeto antes de adaptar os exemplos.</p></section><nav class="lesson-pagination" aria-label="Navegação entre aulas"><a href="index.html">← Visão da trilha</a>{f'<a href="{ls[i]["id"]}.html">Próxima aula →</a>' if i<len(ls) else '<a href="../../consultas.html">Consultar referências →</a>'}</nav></div></article></div>'''
            (td/(l['id']+'.html')).write_text(base(l['title'],body,'../../','catalog','lesson-page',route=f'trilhas/{t["id"]}/{l["id"]}.html'),encoding='utf-8')
    cards=[]
    for r in refs:
        search=' '.join([r['tool'],r['category'],r['name'],r['description'],r['code'],r['dialect'],r.get('use','')])
        detail=''
        if r.get('steps'):
            detail=f'<details class="reference-details"><summary>Como funciona + cuidados</summary><ol>'+''.join(f'<li>{inline(x)}</li>' for x in r['steps'])+'</ol><div class="ref-caution"><strong>Atenção</strong><p>'+inline(r.get('pitfall',''))+'</p></div></details>'
        cards.append(f'''<article class="reference-card glass" id="{E(r['id'])}" data-ref-card data-tool="{E(r['tool'])}" data-search="{E(search)}"><div class="ref-card-top"><span class="tag">{E(r['tool'])}</span><span class="ref-category">{E(r['category'])}</span></div><h2>{E(r['name'])}</h2><p class="ref-purpose">{E(r['description'])}</p>{f'<div class="ref-use"><strong>QUANDO USAR</strong><p>{E(r["use"])}</p></div>' if r.get('use') else ''}{editor(r['code'],r['tool'],r['dialect'],r['name'])}{f'<div class="ref-result"><strong>O QUE ESPERAR</strong><p>{E(r["result"])}</p></div>' if r.get('result') else ''}{detail}<a class="source-link" href="{E(r['source']['url'])}" target="_blank" rel="noopener noreferrer">Documentação oficial ↗<span>{E(r['source']['label'])}</span></a></article>''')
    chips=''.join(f'<button data-ref-tool="{E(tool)}" aria-pressed="false">{E(tool)}</button>' for tool in sorted({r['tool'] for r in refs}))
    refbody=f'''<section class="reference-hero"><span class="eyebrow">CENTRAL DE CONSULTA · {len(refs)} REFERÊNCIAS</span><h1>O código. O contexto.<br><em>O próximo passo.</em></h1><p>Encontre a sintaxe, entenda para que serve e saiba o que esperar antes de aplicar.</p><div class="catalog-controls"><label class="search-field">{svg('search')}<input id="ref-search" type="search" placeholder="Busque por função ou intenção: filtrar, NULL, janela…" aria-label="Pesquisar referências"><kbd>/</kbd></label></div><div class="ref-filter-row" role="group" aria-label="Filtrar ferramenta"><button data-ref-tool="all" aria-pressed="true">Todas <span>{len(refs)}</span></button>{chips}</div><div class="ref-status"><p class="result-count" id="ref-count" role="status">{len(refs)} referências encontradas</p><span>Exemplos didáticos · confirme o dialeto</span></div></section><section class="reference-grid">{''.join(cards)}</section><div class="empty-state" id="ref-empty" hidden><h2>Nada encontrado</h2><p>Tente outro termo ou remova o filtro.</p></div><div class="reference-disclaimer">Os exemplos não são executados pelo portal. Confira versão, esquema, permissões e fonte oficial.</div>'''
    (out/'consultas.html').write_text(base('Consultas rápidas',refbody,active='reference',pageclass='reference-page',route='consultas.html'),encoding='utf-8')

    privacy_body="""<article class="privacy-page"><span class="eyebrow">TRANSPARÊNCIA E CONTROLE</span><h1>Privacidade na Trama</h1><p class="source-note">Versão 2 — revisão de 2026-10-13.</p><p class="lead">Conheça a medição de uso do portal e os controles disponíveis.</p><section><h2>Métricas de uso e aviso informativo</h2><p>Quando habilitadas, as métricas do Google Analytics 4 começam automaticamente nas páginas de produção, sem depender de um botão Aceitar. O pop-up é informativo: Entendi apenas fecha o aviso e não é registrado como consentimento.</p><p>Você pode desativar as métricas no rodapé. Recusas válidas salvas na versão anterior são preservadas. A página de privacidade não carrega a tag do Google Analytics.</p></section><section><h2>O que é enviado</h2><p>O portal envia visualizações de páginas, cliques em aulas, cópias bem-sucedidas de referências, quantidade de resultados de busca e cliques nos links profissionais. Não envia o texto digitado na busca, o código copiado, mensagens, nome ou e-mail.</p><p>O Google processa informações técnicas do acesso, incluindo navegador, dispositivo e localização aproximada, e utiliza identificadores em cookies para distinguir navegadores e sessões. Relatórios agregados não significam anonimato absoluto. Recursos de publicidade e personalização permanecem desativados no código; as configurações externas da propriedade devem ser revisadas pelo responsável.</p><p>A medição é restrita ao domínio e caminho publicados da Trama. Pré-visualizações locais não coletam. O provedor de hospedagem GitHub Pages pode tratar IP e logs técnicos necessários à entrega das páginas, independentemente do GA4.</p></section><section><h2>Cookies e armazenamento local</h2><p>Sim, o GA4 usa cookies analíticos nesta configuração. Eles têm prefixo exclusivo da Trama, domínio host-only, caminho do portal e prazo configurado de até 180 dias por gravação. Não registram progresso dos cursos nem correspondem a um cadastro no portal.</p><p>O armazenamento local guarda separadamente a dispensa deste aviso e a preferência de ativar/desativar métricas, com versão e validade de até 180 dias. Isso não é uma prova de consentimento. Se o armazenamento estiver indisponível no carregamento, a coleta automática fica desativada; o controle pode funcionar somente nesta página.</p><p>A retenção no serviço Google é uma configuração separada da propriedade; o responsável deve conferir o prazo efetivo e os procedimentos de exclusão com o serviço.</p></section><section><h2>Como desativar métricas</h2><p>Use Desativar métricas no rodapé. Isso bloqueia novos disparos do portal, remove os cookies analíticos da Trama acessíveis ao site e, quando a preferência foi salva e a tag já carregou, recarrega a página. Não remove cookies do portfólio nem apaga automaticamente dados já enviados. Uma requisição já em trânsito pode terminar.</p><p>Para reativar, use Ativar métricas no mesmo lugar. Fechar ou reabrir o aviso informativo não muda essa preferência.</p></section><section><h2>Finalidade, base legal e seus direitos</h2><p>A finalidade é compreender o uso das páginas e melhorar o portal. Um aviso informativo não substitui a definição e a avaliação da base legal aplicável. Esta versão descreve a implementação solicitada pelo responsável e não declara conformidade jurídica certificada.</p><p>Antes de publicar este modo de coleta, cabe ao responsável confirmar e documentar a base legal, as salvaguardas, o uso do fornecedor e as regras aplicáveis aos públicos atendidos. Não se presume que o uso de cookies ou identificadores esteja fora da LGPD. Dúvidas, pedidos de informação, oposição ou exclusão podem ser encaminhados pelo contato indicado abaixo; a possibilidade de atendimento depende dos dados efetivamente disponíveis e dos serviços envolvidos.</p></section><section><h2>Contato e serviços externos</h2><p>Responsável pelo portal: Kaíque Passaros. Use a página de Contato e sugestões vinculada no rodapé para assuntos de privacidade. O formulário fica no portfólio, não é incorporado à Trama; revise os termos e políticas do serviço de destino antes de enviar dados.</p><p>Portfólio, LinkedIn e demais fontes externas abrem por escolha sua e têm práticas próprias. <a href="https://policies.google.com/privacy?hl=pt-BR" target="_blank" rel="noopener noreferrer">Política de privacidade do Google ↗</a></p></section></article>"""
    terms_body="""<article class="privacy-page"><span class="eyebrow">FINALIDADE E LIMITES</span><h1>Termos de Uso da Trama</h1><p class="source-note">Versão 1 — revisão de 2026-10-13.</p><p class="lead">Um portal pessoal de estudo e consulta, com exemplos didáticos e fontes oficiais.</p><section><h2>Uso do conteúdo</h2><p>A Trama oferece trilhas introdutórias e referências para apoiar o estudo. O conteúdo não substitui documentação oficial, treinamento certificado ou validação no seu ambiente. Não há garantia de currículo completo, resultado profissional, funcionamento em todas as versões ou disponibilidade contínua.</p></section><section><h2>Exemplos e segurança</h2><p>Os exemplos usam dados fictícios e não são executados contra suas ferramentas pelo portal. Antes de adaptar, confira permissões, versão, dialeto, localidade, esquema e riscos. Não publique credenciais, segredos, dados reais ou material interno em exemplos ou solicitações de contato.</p><p>Testes documentados têm escopo específico; não representam auditoria integral de segurança, acessibilidade ou compatibilidade. Faça backups e validação adequada antes de usar qualquer exemplo em produção.</p></section><section><h2>Autoria e licenças</h2><p>Projeto pessoal de Kaíque Passaros. Fontes e materiais de terceiros conservam seus créditos e termos próprios. Consultar ou copiar um exemplo não concede automaticamente licença para redistribuir o portal, sua marca ou materiais de terceiros. Uma licença global de distribuição do projeto não é declarada nestes termos.</p></section><section><h2>Privacidade e links externos</h2><p>A medição de uso, os cookies e os controles estão descritos em Privacidade, acessível no rodapé. Estes termos não substituem consentimento quando ele for necessário e não afirmam que navegar representa autorização genérica para tratamento de dados.</p><p>Sites de documentação, portfólio, formulário de contato e LinkedIn são serviços externos. Confira as práticas do destino antes de interagir ou enviar informações.</p></section><section><h2>Atualizações e contato</h2><p>Conteúdo e funcionalidades podem ser revisados. Alterações relevantes devem ser refletidas nestes documentos. Para correções, sugestões ou dúvidas, use Contato e sugestões no rodapé. Estes termos não afastam direitos previstos na legislação aplicável nem constituem parecer jurídico.</p></section></article>"""
    (out/'privacidade.html').write_text(base('Privacidade',privacy_body,pageclass='privacy-site-page',route='privacidade.html'),encoding='utf-8')
    (out/'termos.html').write_text(base('Termos de Uso',terms_body,pageclass='terms-site-page',route='termos.html'),encoding='utf-8')
